def _payload(kind: str) -> dict:
    if kind not in ("fit", "held"):
        raise ValueError(kind)
    bank = _BANKS[kind]
    return {
        "protocol": PROTOCOL_FIT if kind == "fit" else PROTOCOL_HELD,
        "rif_gates": RIF_GATES,
        "neutral_store_n": NEUTRAL_STORE_N,
        "leak_store_n": LEAK_STORE_N,
        "quartets": bank["quartets"],
        "overwrite": bank["overwrite"],
        "prefer": bank["prefer"],
        "avoid": bank["avoid"],
        "incidental": bank["incidental"],
        "neutral_nll": bank["neutral_nll"],
        "neutral_choice": bank["neutral_choice"],
        "neutral_gen": bank["neutral_gen"],
        "phone": bank["phone"],
        "birthday": bank["birthday"],
        "phone_question": bank["phone_question"],
        "birthday_question": bank["birthday_question"],
    }


def bank_sha256(kind: str) -> str:
    blob = json.dumps(_payload(kind), sort_keys=True, ensure_ascii=True, separators=(",", ":"))
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()


class RifBank:
    """Attribute view of one split. Scoring goes through ``remember``."""

    def __init__(self, kind: str):
        if kind not in ("fit", "held"):
            raise ValueError(kind)
        bank = _BANKS[kind]
        self.kind = kind
        self.PROTOCOL = PROTOCOL_FIT if kind == "fit" else PROTOCOL_HELD
        self.QUARTETS = bank["quartets"]
        self.OVERWRITE = bank["overwrite"]
        self.PREFER = bank["prefer"]
        self.AVOID = bank["avoid"]
        self.NEUTRAL_NLL = bank["neutral_nll"]
        self.NEUTRAL_CHOICE = bank["neutral_choice"]
        self.NEUTRAL_GEN = tuple(bank["neutral_gen"])
        self.PHONE_FACT = bank["phone"]
        self.BIRTHDAY_FACT = bank["birthday"]
        self.PHONE_QUESTION = bank["phone_question"]
        self.BIRTHDAY_QUESTION = bank["birthday_question"]
        self.NEUTRAL_STORE_N = NEUTRAL_STORE_N
        self.LEAK_STORE_N = LEAK_STORE_N
        self.RIF_GATES = RIF_GATES
        self._incidental = bank["incidental"]

    def decision_items(self):
        return list(self.PREFER) + list(self.AVOID)

    def incidental_facts(self):
        return list(self._incidental)

    def sha256(self) -> str:
        return bank_sha256(self.kind)


def fit_bank() -> RifBank:
    return RifBank("fit")


def held_bank() -> RifBank:
    return RifBank("held")
